   let names={STY:'Styrka',FYS:'Fysik',STO:'Storlek',SMI:'Smidighet',INT:'Intelligens',PSY:'Psykisk kraft',KAR:'Karisma'};
   let baseKey=names[bc]||Object.keys(c?.base||{}).find(k=>k.toLocaleUpperCase('sv-SE')===bc)||null;
