async function syncCharacterToCentral(c){if(!centralReady||!centralCampaignId||!supabaseSession||!c)return;let body={campaign_id:centralCampaignId,owner_id:(typeof c.ownerId==='string'&&/^[0-9a-f]{8}-[0-9a-f-]{27}$/i.test(c.ownerId))?c.ownerId:null,name:c.identity?.namn||'Namnlös',is_npc:c.ownerId==='SLP',schema_version:ALEA_SCHEMA_VERSION,combat_icon_path:c.combatIconPath||null,data:cleanCharacterForDb(c)};if(c._dbId){await dbJson('characters?id=eq.'+encodeURIComponent(c._dbId),{method:'PATCH',body:JSON.stringify(body)});}else{body.created_by=supabaseSession.user.id;let rows=await dbJson('characters',{method:'POST',body:JSON.stringify(body)});if(rows?.[0])c._dbId=rows[0].id}}
