async function advanceCampaignDay(withRest){
 if(!campaignDayManager()||!centralCampaignId)return;
 let weather=$('nextDayWeather')?.value||'',next=(Number(campaignDayState?.day_number)||1)+1;
 let restHours=withRest?Math.max(0,Number($('nextDayRestHours')?.value)||0):0;
 if(withRest&&restHours<=0){alert('Ange vilotid i timmar.');return}
 let fullHours=Math.floor(restHours);
 let msg=withRest
  ?restHours+' h vila. Varje rollperson återfår '+fullHours+' PSY upp till max. ERF-gränsen nollställs vid minst 6 h vila, eller 2 h för alla raser i kategorin Älvfolk.'
  :'Ingen vila. PSY återhämtas inte och ERF-gränsen nollställs inte.';
 if(weather)msg+='\nVäder: '+weather;
 let ok=await askConfirm('Starta dag '+next,msg,'Starta dag');
 if(!ok)return;
 let keepDbId=current?._dbId||null,keepLocalId=current?.id||null;
 clearTimeout(centralSaveTimer);
 try{
  let x=await dbJson('rpc/advance_campaign_day',{method:'POST',body:JSON.stringify({p_campaign_id:centralCampaignId,p_weather:weather,p_rest_hours:restHours})});
  campaignDayState=Array.isArray(x)?x[0]:x;
  await loadCentralData();
  current=keepDbId?chars.find(c=>c._dbId===keepDbId):keepLocalId?chars.find(c=>c.id===keepLocalId):current;
  await loadCampaignDayState();
  renderCampaignDayHeader();renderCampaignDayModal();
  if(current)render();else renderCards();
  showBackupToast('✓ Dag '+campaignDayState.day_number+' startad · '+restHours+' h vila')
 }catch(e){alert('Kunde inte starta ny dag: '+e.message)}
}
