function sitePath(siteId){
 let seen=new Set(),parts=[],id=siteId;
 while(id&&!seen.has(id)){seen.add(id);let s=campaignSites.find(x=>x.id===id);if(!s)break;parts.unshift(s.name||s.site_key||'Plats');id=s.parent_site_id}
 return parts.join(' › ')||'—';
}
function campaignLocationLabel(l){return l?sitePath(l.site_id)+' › '+(l.location_key?l.location_key+'. ':'')+(l.name||'Plats'):'Okänd plats'}
function eventLocationLinks(eventId){return campaignLocationEventLinks.filter(x=>x.event_id===eventId)}
function locationEventLinks(locationId){return campaignLocationEventLinks.filter(x=>x.location_id===locationId)}
function eventPrimaryLocation(eventId){
 let links=eventLocationLinks(eventId),link=links.find(x=>x.relation_kind==='primary')||links[0];
 return link?campaignLocations.find(l=>l.id===link.location_id)||null:null
}
function eventPlaceSummary(eventId){
 let links=eventLocationLinks(eventId);if(!links.length)return 'Ingen plats kopplad';
 let p=eventPrimaryLocation(eventId),extra=Math.max(0,links.length-1);
 return (p?campaignLocationLabel(p):links.length+' platser')+(extra?' +'+extra:'')
}
function locationEventSummary(locationId){
 let rows=locationEventLinks(locationId).map(x=>campaignEvents.find(e=>e.id===x.event_id)).filter(Boolean);
 if(!rows.length)return '';
 return rows.slice(0,2).map(e=>e.name||'Händelse').join(', ')+(rows.length>2?' +'+(rows.length-2):'')
}
