function normalizeSiteKey(name){
 return String(name||'').trim().toUpperCase().replace(/Å/g,'A').replace(/Ä/g,'A').replace(/Ö/g,'O').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^A-Z0-9]+/g,'-').replace(/^-+|-+$/g,'')||'PLATS';
}
function makeUniqueSiteKey(name,parentId=null,excludeId=''){
 let base=normalizeSiteKey(name),candidate=base,n=2;
 let used=k=>campaignSites.some(s=>s.id!==excludeId&&(s.parent_site_id||null)===(parentId||null)&&String(s.site_key||'').toUpperCase()===k.toUpperCase());
 while(used(candidate))candidate=base+'-'+n++;
 return candidate;
}
function nextLocationKey(siteId,excludeId=''){
 let used=new Set(campaignLocations.filter(l=>l.site_id===siteId&&l.id!==excludeId).map(l=>String(l.location_key||'').trim()));
 let n=1;while(used.has(String(n)))n++;return String(n);
}
function updateAutoSiteKey(){
 let name=$('asName')?.value||'',parent=$('asParent')?.value||null,key=$('asKey');if(key)key.value=makeUniqueSiteKey(name,parent);
}
function updateAutoLocationKey(){
 let site=$('alSite')?.value,key=$('alKey');if(site&&key)key.value=nextLocationKey(site);
}
