async function getLocationAssetUrl(asset){
 let cached=locationAssetUrlCache.get(asset.storage_path);if(cached)return cached;
 let r=await locationAssetStorageFetch('object/campaign-location-assets/'+encodeStoragePath(asset.storage_path),{method:'GET'});
 if(!r.ok)throw new Error('Kunde inte läsa bilden ('+r.status+').');
 let blob=await r.blob(),url=URL.createObjectURL(blob);locationAssetUrlCache.set(asset.storage_path,url);return url;
}
