function areaShapePoints(a){
 if(a?.shape_type==='rect'){let d=a.shape_data||{},x=Number(d.x)||0,y=Number(d.y)||0,w=Number(d.width)||0,h=Number(d.height)||0;return[[x,y],[x+w,y],[x+w,y+h],[x,y+h]]}
 return Array.isArray(a?.shape_data?.points)?a.shape_data.points.map(p=>[Number(p[0]),Number(p[1])]).filter(p=>p.every(Number.isFinite)):[];
}
function pointOnSegment(p,a,b,eps=.001){
 let cross=(p[1]-a[1])*(b[0]-a[0])-(p[0]-a[0])*(b[1]-a[1]);if(Math.abs(cross)>eps)return false;
 let dot=(p[0]-a[0])*(b[0]-a[0])+(p[1]-a[1])*(b[1]-a[1]);if(dot<-eps)return false;
 let len=(b[0]-a[0])**2+(b[1]-a[1])**2;return dot<=len+eps;
}
function pointInPolygonStrict(p,poly){
 for(let i=0,j=poly.length-1;i<poly.length;j=i++)if(pointOnSegment(p,poly[j],poly[i]))return false;
 let inside=false;for(let i=0,j=poly.length-1;i<poly.length;j=i++){let xi=poly[i][0],yi=poly[i][1],xj=poly[j][0],yj=poly[j][1];let hit=((yi>p[1])!==(yj>p[1]))&&(p[0]<(xj-xi)*(p[1]-yi)/(yj-yi)+xi);if(hit)inside=!inside}return inside;
}
function orient(a,b,c){return(b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0])}
function segmentsProperIntersect(a,b,c,d){
 let o1=orient(a,b,c),o2=orient(a,b,d),o3=orient(c,d,a),o4=orient(c,d,b),eps=.001;
 return ((o1>eps&&o2<-eps)||(o1<-eps&&o2>eps))&&((o3>eps&&o4<-eps)||(o3<-eps&&o4>eps));
}
function polygonsOverlap(a,b){
 if(a.length<3||b.length<3)return false;
 for(let p of a)if(pointInPolygonStrict(p,b))return true;
 for(let p of b)if(pointInPolygonStrict(p,a))return true;
 for(let i=0;i<a.length;i++){let a2=a[(i+1)%a.length];for(let j=0;j<b.length;j++)if(segmentsProperIntersect(a[i],a2,b[j],b[(j+1)%b.length]))return true}
 let ca=[a.reduce((s,p)=>s+p[0],0)/a.length,a.reduce((s,p)=>s+p[1],0)/a.length],cb=[b.reduce((s,p)=>s+p[0],0)/b.length,b.reduce((s,p)=>s+p[1],0)/b.length];
 return pointInPolygonStrict(ca,b)||pointInPolygonStrict(cb,a);
}
function draftOverlapsExisting(){return mapAreaDraft.length>=3&&mapAreaEditAreas.some(a=>polygonsOverlap(mapAreaDraft,areaShapePoints(a)))}
function renderMapAreaEditor(){
 if(!mapAreaEditMap)return;
 let svg=$('mapAreaSvg'),overlap=draftOverlapsExisting();
 let existing=mapAreaEditAreas.map(a=>{let pts=areaShapePoints(a).map(p=>p.join(',')).join(' ');return`<polygon class="map-editor-zone" data-area-id="${escAttr(a.id)}" points="${escAttr(pts)}" onclick="mapAreaExistingClick(event,'${a.id}')"><title>${escAttr(a.name||'Plats')}</title></polygon>`}).join('');
 let draft=mapAreaDraft.length?`<polygon class="map-editor-draft ${overlap?'overlap':''}" points="${mapAreaDraft.map(p=>p.join(',')).join(' ')}"></polygon>${mapAreaDraft.map(p=>`<circle class="map-editor-point" cx="${p[0]}" cy="${p[1]}" r="5"></circle>`).join('')}`:'';
 svg.innerHTML=existing+draft;
 let locMap=new Map(campaignLocations.map(l=>[l.id,l]));
 $('mapAreaList').innerHTML=mapAreaEditAreas.length?mapAreaEditAreas.map((a,i)=>{let l=locMap.get(a.location_id);let options='<option value="">Ingen plats</option>'+campaignLocations.map(x=>`<option value="${x.id}" ${a.location_id===x.id?'selected':''}>${escAttr(sitePath(x.site_id)+' › '+x.location_key+'. '+x.name)}</option>`).join('');let pills=mapStatusPillsHtml(a);return`<div class="map-area-list-row"><div><b>Polygon ${i+1}</b><div class="muted">${l?'Kopplad':'Ej kopplad'}</div></div><select onchange="assignMapAreaLocation('${a.id}',this.value)" aria-label="Koppla polygon ${i+1} till plats">${options}</select><div class="map-status-pills">${pills}</div><button class="deletebtn" onclick="deleteMapArea('${a.id}')">×</button></div>`}).join(''):'<div class="map-area-empty">Inga polygoner definierade ännu.</div>';
 $('mapAreaUndoBtn').disabled=!mapAreaDrawing||!mapAreaDraft.length;$('mapAreaSaveBtn').disabled=!mapAreaDrawing||mapAreaDraft.length<3||overlap;
 $('mapAreaStartBtn').disabled=mapAreaDrawing;$('mapAreaCancelBtn').classList.toggle('hidden',!mapAreaDrawing);
 let n=$('mapAreaNotice');if(overlap){n.textContent='Polygonen överlappar ett befintligt område och kan inte sparas.';n.classList.add('error')}else{n.textContent=mapAreaDrawing?('Klicka ut minst tre hörnpunkter. Magnetisk fästning mot närliggande '+(mapAreaLastSnap||'hörn och kanter')+'.'):('Gap är tillåtna. Överlapp blockeras. Nya punkter fäster automatiskt mot närliggande hörn och kanter.');n.classList.remove('error')}
}
