function closeDice(){$('dicePage').classList.add('hidden');if(diceReturn==='combat'){$('combatPage').classList.remove('hidden')}else if(diceReturn==='map'){$('mapPage').classList.remove('hidden')}else if(diceReturn==='view'&&current){$('view').classList.remove('hidden');$('back').classList.remove('hidden');$('editBtn').classList.remove('hidden')}else if(diceReturn==='admin'&&activeUser()?.admin){$('admin').classList.remove('hidden')}else{$('home').classList.remove('hidden');renderCards()}}
function secureDie(sides){let max=0x100000000-(0x100000000%sides),a=new Uint32Array(1),v;do{crypto.getRandomValues(a);v=a[0]}while(v>=max);return(v%sides)+1}
function diceExpression(rolls){let counts={};rolls.forEach(r=>counts[r.sides]=(counts[r.sides]||0)+1);return DICE_SIDES.filter(s=>counts[s]).map(s=>counts[s]+'T'+s).join(' + ')}
function dieSvg(s,v){let t=String(v);
if(s===3)return `<svg viewBox="0 0 100 100"><polygon class="face-main" points="50,7 94,88 6,88"/><path class="face-mid" d="M50 7L50 88L6 88Z"/><path class="edge" d="M50 7L50 88M6 88L94 88"/><text x="55" y="61">${t}</text></svg>`;
if(s===4)return `<svg viewBox="70 90 600 550" aria-label="T4 ${t}"><path class="face-main" d="M367.54,113.2l33.14,507.22-306.93-183Z"/><path class="face-mid" d="M645.2,424.74,387.87,117.65l32.7,500.44Z"/><text class="die-number d4num" x="363" y="350">${t}</text></svg>`;
if(s===6)return `<svg viewBox="0 0 100 100" aria-label="T6 ${t}"><rect class="face-main" x="8" y="8" width="84" height="84" rx="3"/><path class="edge" d="M8 8H92V92H8Z"/><text class="die-number d6num" x="50" y="52">${t}</text></svg>`;
if(s===8)return `<svg viewBox="1435 115 535 485" aria-label="T8 ${t}"><path class="face-main" d="M1546.21,254.29l230.41,318.45-313.77-59Z"/><path class="face-mid" d="M1796.77,566.47l144.85-372.2-380.84,46Z"/><path class="face-light" d="M1885.58,180.9l-259.22-42L1565,219.66Z"/><text class="die-number d8num" x="1850" y="390">${t}</text></svg>`;
if(s===10||s===100)return `<svg viewBox="0 0 100 100" aria-label="T${s} ${t}"><polygon class="face-light" points="50,3 72,18 64,43 50,34 36,43 28,18"/><polygon class="face-mid" points="28,18 36,43 50,96 8,58"/><polygon class="face-main" points="36,43 50,34 64,43 50,96"/><polygon class="face-dark" points="64,43 72,18 92,58 50,96"/><path class="edge" d="M50 3L50 34M28 18L72 18M8 58L50 96L92 58"/><text class="die-number d10num" x="50" y="61">${t}</text></svg>`;
return `<svg viewBox="1390 705 660 620" aria-label="T20 ${t}"><g class="source-d20"><path class="face-dark" d="M1938.64,1144.5l-283.76,163.67-37.3-282.8Z"/><path class="face-mid" d="M1405.49,1077.68l227.78,219.57L1597.1,1023Z"/><path class="face-light" d="M1849.82,784.59l-321.94-25.12L1610,993Z"/><path class="face-mid" d="M1780,722.22l-172.5,23.4,231.34,18.06Z"/><path class="face-dark" d="M1512.85,777l-110.11,280.68,189.8-54.15Z"/><path class="face-light" d="M1898.58,1267.47L1941.31,1166l-238.9,137.8Z"/><path class="face-mid" d="M2033.68,946.87L1892.23,808l72.47,302.55Z"/><path class="face-main" d="M1624.78,1006.72L1948,1126.63l-79.47-331.79Z"/><text class="die-number d20num" x="1810" y="1010">${t}</text></g></svg>`}

function dieLanding(i,n){let cols=Math.max(2,Math.ceil(Math.sqrt(n))),rows=Math.ceil(n/cols),col=i%cols,row=Math.floor(i/cols),jx=(secureDie(17)-9)/100,jy=(secureDie(17)-9)/100;return{x:Math.max(2,Math.min(84,((col+.5)/cols)*100-8+jx*25)),y:Math.max(2,Math.min(82,((row+.5)/rows)*100-9+jy*25))}}

async function rollSelectedDice(){if(diceRolling)return;if(diceRollContext?.type==='skill'&&diceRollContext.skillPhase==='done'){diceRollContext.skillPhase='initial';diceRollContext.skillFirstRoll=null;diceRollContext.skillSecondRoll=null;diceRollContext.skillOutcome=null;diceRollContext.skillConfirmKind=null;}let specs=[];DICE_SIDES.forEach(s=>{for(let i=0;i<(diceSelection[s]||0);i++)specs.push(s)});if(!specs.length){$('diceResult').innerHTML='<div class="muted">Välj minst en tärning först.</div>';return}
if(diceRollContext?.type==='spell'&&specs.length===1&&specs[0]===20){
 let cost=Math.max(1,Math.floor(Number(diceRollContext.effectGrade)||1)),psy=Math.max(0,Number(current?.live?.PSY)||0);
 if(cost>psy){$('diceResult').innerHTML=`<div class="dice-context">Besvärjelse: <b>${escAttr(diceRollContext.spellName||'Besvärjelse')}</b> · Effektgrad <b>${cost}</b></div><div class="roll-outcome fail">INTE TILLRÄCKLIGT MED PSY</div>`;return}
 if(cost===psy){
  let ok=await askConfirm('Sista PSY-poängen',`Effektgrad ${cost} förbrukar dina sista ${cost===1?'PSY-poäng':'PSY-poäng'} och lämnar dig på 0 PSY. Vill du verkligen använda din sista PSY-poäng?`,'Använd PSY',true);
  if(!ok){$('diceResult').innerHTML='<div class="muted">Besvärjelsen avbröts. Ingen PSY förbrukades.</div>';return}
 }
 diceRollContext.psyBefore=psy;current.live.PSY=Math.max(0,psy-cost);diceRollContext.psyAfter=current.live.PSY;
 save();renderQuickOnly();
}
diceRolling=true;$('rollDiceBtn').disabled=true;if(diceRollContext?.type==='skill'&&diceRollContext.skillPhase==='confirm'&&diceRollContext.skillFirstRoll!=null){$('diceResult').innerHTML=skillRollContextLine(diceRollContext)+`<div class="skill-roll-sequence"><span>Första: <b>${diceRollContext.skillFirstRoll}</b></span></div><div class="skill-roll-note">Kontrollslaget rullar…</div>`}else $('diceResult').innerHTML='<div class="muted">Tärningarna rullar…</div>';
let can3d=typeof window.alea3dRoll==='function';
if(can3d){try{$('diceStage').innerHTML='';$('diceStage').classList.remove('fallback-only');
let notation=DICE_SIDES.filter(s=>diceSelection[s]).map(s=>({qty:diceSelection[s],sides:s===3?6:s}));
let result=await window.alea3dRoll(notation);
let raw=(Array.isArray(result)?result:[]).map(r=>({sides:Number(String(r.sides??'').replace(/^d/i,'')),value:Number(r.value)})).filter(r=>validDieValue(r.value,r.sides));
if(!raw.length)throw new Error('Inga giltiga 3D-resultat');
let pools={};raw.forEach(r=>(pools[r.sides]||(pools[r.sides]=[])).push(r.value));
let rolls=[];
DICE_SIDES.forEach(s=>{
 let n=diceSelection[s]||0;
 for(let i=0;i<n;i++){
  if(s===3){
   let d6=(pools[6]||[]).shift();
   if(!Number.isFinite(d6))throw new Error('Saknar T6-resultat för T3');
   rolls.push({sides:3,value:Math.ceil(d6/2),sourceSides:6,sourceValue:d6});
  }else{
   let v=(pools[s]||[]).shift();
   if(!Number.isFinite(v))throw new Error('Saknar T'+s+'-resultat');
   rolls.push({sides:s,value:v});
  }
 }
});
if(rolls.length!==specs.length||rolls.some(r=>!validDieValue(r.value,r.sides)))throw new Error('Ofullständigt eller ogiltigt 3D-resultat');
let total=rolls.reduce((a,r)=>a+r.value,0);
renderDiceRollResult(rolls,total);
diceRolling=false;$('rollDiceBtn').disabled=false;return}catch(e){console.error('3D-tärningar misslyckades, använder SVG-reserv',e);if(window.alea3dStatus)window.alea3dStatus('3D-motor: reservläge','error',e)}}
let rolls=specs.map((s,i)=>{let raw=s===3?secureDie(6):secureDie(s);return{sides:s,value:s===3?Math.ceil(raw/2):raw,sourceSides:s===3?6:s,sourceValue:raw,pos:dieLanding(i,specs.length)}}),stage=$('diceStage');stage.classList.add('fallback-only');stage.innerHTML=rolls.map((r,i)=>{let side=i%2?-1:1,sx=side*(110+secureDie(80)),sy=-80-secureDie(90),base=secureDie(180)-90;return `<div class="svg-die d${r.sides} rolling" style="left:${r.pos.x}%;top:${r.pos.y}%;--sx:${sx}px;--sy:${sy}px;--r0:${base}deg;--r1:${base+280*side}deg;--r2:${base+510*side}deg;--r3:${base+690*side}deg;--r4:${base+790*side}deg;--rf:${secureDie(21)-11}deg;animation-delay:${Math.min(i*55,330)}ms" title="T${r.sides}: ${r.value}">${dieSvg(r.sides,r.value)}</div>`}).join('');await new Promise(r=>setTimeout(r,1650));[...stage.querySelectorAll('.svg-die')].forEach(el=>el.classList.remove('rolling'));let total=rolls.reduce((a,r)=>a+r.value,0);renderDiceRollResult(rolls,total);diceRolling=false;$('rollDiceBtn').disabled=false}

